import { type ParentComponent } from "solid-js";

import { Activatable, type ActivatableProps } from "#core/ui-next/components/activatable.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { FocusManager } from "#core/ui-next/services/focus-manager.js";

export interface SubSystemButtonProps extends ActivatableProps {
	tooltip: string;
	bgImg: string;
	tutorialHighlight?: string;
}

const SubSystemButtonComponent: ParentComponent<SubSystemButtonProps> = (props) => {
	const onActivate = () => {
		props.onActivate?.();

		const focusedElement = document.activeElement;
		if (focusedElement instanceof HTMLElement) {
			FocusManager.get().clearFocus(focusedElement);
		}
	};

	return (
		<Activatable
			{...props}
			disableFocus={props.disableFocus ?? true}
			onActivate={onActivate}
			class={`ssb__button ssb__element ${props.class ?? ""}`}
			data-tut-highlight={props.tutorialHighlight ?? "founderHighlight"}
			data-tooltip-content={Locale.compose(props.tooltip)}
			audio={{
				group: "audio-panel-sub-system-dock",
				onFocus: "data-audio-focus",
				onPress: "data-audio-press-small",
				onActivate: "none",
				...props.audio,
			}}
			name={"SubSystemButton-" + props.name}
		>
			{props.children}
			<div class={`ssb__button-iconbg`} />
			<div class={`ssb__button-iconbg ssb__button-iconbg--hover`} />
			<div class={`ssb__button-iconbg ssb__button-iconbg--active`} />
			<div class={`ssb__button-iconbg ssb__button-iconbg--disabled`} />
			<div
				class={`ssb__button-icon`}
				style={{ "background-image": props.bgImg }}
			/>
		</Activatable>
	);
};

export const SubSystemButton = ComponentRegistry.register({
	name: "SubSystemButton",
	createInstance: SubSystemButtonComponent,
	images: ["blp:hud_sub_circle_bk", "blp:hud_sub_circle_hov", "blp:hud_sub_circle_prs", "blp:hud_sub_circle_dis"],
});
